public class InnerAutoMLJobTabularJobConfigFactory(Action<Humidifier.SageMaker.AutoMLJobTypes.TabularJobConfig> factoryAction = null) : SubResourceFactory<Humidifier.SageMaker.AutoMLJobTypes.TabularJobConfig>
{

    internal InnerAutoMLJobCandidateGenerationConfigFactory CandidateGenerationConfigFactory { get; set; }

    internal InnerAutoMLJobAutoMLJobCompletionCriteriaFactory CompletionCriteriaFactory { get; set; }

    protected override Humidifier.SageMaker.AutoMLJobTypes.TabularJobConfig Create()
    {
        var tabularJobConfigResult = CreateTabularJobConfig();
        factoryAction?.Invoke(tabularJobConfigResult);

        return tabularJobConfigResult;
    }

    private Humidifier.SageMaker.AutoMLJobTypes.TabularJobConfig CreateTabularJobConfig()
    {
        var tabularJobConfigResult = new Humidifier.SageMaker.AutoMLJobTypes.TabularJobConfig();

        return tabularJobConfigResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.AutoMLJobTypes.TabularJobConfig result)
    {
        base.CreateChildren(result);

        result.CandidateGenerationConfig ??= CandidateGenerationConfigFactory?.Build();
        result.CompletionCriteria ??= CompletionCriteriaFactory?.Build();
    }

} // End Of Class

